//! `evaluate_confidence` against the table that the .NET `EvaluateConfidence` produced
//! (`rust/tests/golden/confidence.json`, regenerated by `rust/tools/confidence-oracle`).

use serde_json::Value;
use sermofur_core::confidence::evaluate_confidence;
use sermofur_core::format::DateTimeOffset;
use sermofur_core::records::{MemoryRecord, read, write};

#[test]
fn confidence_matches_the_oracle() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/confidence.json"
    );
    let golden: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden file")).expect("JSON");
    let offset = |_| 0;
    let cases = golden["cases"].as_array().expect("cases");
    assert!(cases.len() > 400, "crafted and random cases");
    let mut mismatches = Vec::new();
    for case in cases {
        let name = case["name"].as_str().expect("name");
        let claim: MemoryRecord =
            read(case["claim"].as_str().expect("claim"), &offset).expect("a claim");
        let evidence: Vec<MemoryRecord> = case["evidence"]
            .as_array()
            .expect("evidence")
            .iter()
            .map(|e| read(e.as_str().expect("evidence"), &offset).expect("evidence"))
            .collect();
        // Review dates of the table lie in 2001 or 2199: the present instant never decides.
        let actual = evaluate_confidence(&claim, &evidence, DateTimeOffset::now_utc(), &offset)
            .map(|c| write(&c).expect("written").replace("\r\n", "\n"));
        let expected = case["confidence"].as_str().map(|c| c.replace("\r\n", "\n"));
        if actual.as_ref().ok() != expected.as_ref() {
            mismatches.push(format!("{name}: expected {expected:?}, got {actual:?}"));
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}
